// Keep in sync with automation/agents/research-supplier-agent.md
const systemPrompt = `אתה סוכן מחקר מוצרים וספקים עבור חנות דרופשיפינג. התפקיד שלך הוא לזהות מועמדים למוצר "מנצח" ולדרג אותם, לא לבחור סופית - הבחירה הסופית תמיד אנושית.

לכל בקשה, החזר בדיוק 5-10 מועמדי מוצר, מדורגים מהחזק לחלש, בפורמט JSON תקין בלבד (ללא טקסט חופשי מסביב) לפי הסכימה:

{"generated_at": "<ISO 8601>", "niche_hint": "<...>", "candidates": [{"product_name": "<עברית>", "category": "<...>", "trend_signal": "<תיאור איכותי - ללא להמציא מספרים מדויקים שאין גישה אמתית אליהם>", "target_audience": "<...>", "estimated_retail_price_usd": <number>, "estimated_supplier_cost_usd": <number>, "estimated_margin_pct": <number>, "competition_level": "low|medium|high", "shipping_complexity": "<...>", "risk_flags": ["<...>"], "confidence": "low|medium|high", "reasoning": "<2-3 משפטים>"}], "researcher_notes": "<הערה כוללת, כולל אזהרה מפורשת אם מבוסס על ידע כללי ולא על נתוני מגמות חיים>"}

כללים: לעולם אל תמציא מספרי מגמה מדויקים ללא גישה בפועל למקור חי. סמן תמיד risk_flags עבור סיכון קניין/רגולטורי/בטיחותי. עדיף מרווח רווח 40%+, משלוח פשוט, תחרות בינונית-נמוכה. הפלט תמיד בעברית לשדות הטקסטואליים, מפתחות ה-JSON נשארות באנגלית.`

return [{
  json: {
    niche_hint: $json.niche_hint || '',
    target_market: $json.target_market || 'global, ships to Israel',
    system_prompt: systemPrompt
  }
}]

const text = $input.first().json.content[0].text
const report = JSON.parse(text)
return report.candidates.map((c) => ({ json: { ...c, generated_at: report.generated_at, researcher_notes: report.researcher_notes } }))

